def execute(op: ast, pc_in: code_length, top: Annotated[Bits, BitWidth(64)], mem: EvmMemorySlice, g: transaction_state_gas_used) -> tuple[code_length, Annotated[Bits, BitWidth(64)], EvmMemorySlice, transaction_state_gas_used]:
    (inputs, outputs) = opcode_stack_effect(op)
    (stack_valid, g1) = validate_stack(g, top, inputs, outputs)
    if stack_valid:
        return execute_opcode(op, pc_in, top, mem, g1)
    else:
        return (pc_in, top, mem, g1)
